package kernels

// gemm32 is the float32 GEMM on the 8x16 LASX kernel (gemmMicro8x16LASX in
// sum_loong64.s, generated by go-asmgen; see asmgen/loong64/gen.go). Without
// LASX there is none, and float32 products are computed in float64.
var gemm32 = newGemm32(useLASX)

func newGemm32(lasx bool) *gemmKernel[float32] {
	if !lasx {
		return nil
	}
	return &gemmKernel[float32]{mr: 8, nr: 16, micro: gemmMicro32}
}

// gemmMicro32 adds the 8 x 16 tile sum_p pa[p*8..]*pb[p*16..] into the C block
// at dst[0:], whose rows are ldc apart. pa, pb hold at least kc*8 and kc*16
// packed (zero-padded) floats; dst has at least 7*ldc + 16 elements.
func gemmMicro32(kc int, pa, pb, dst []float32, ldc int) {
	_, _, _ = pa[kc*8-1], pb[kc*16-1], dst[7*ldc+15] // the kernel's whole reach
	gemmMicro8x16LASX(kc, &pa[0], &pb[0], &dst[0], ldc)
}

